import pandas as pd


def _is_null(v):
    try:
        return pd.isna(v)
    except Exception:
        return v is None


def _eq_nullable(a, b):
    a_null = _is_null(a)
    b_null = _is_null(b)
    if a_null and b_null:
        return True
    if a_null != b_null:
        return False
    return a == b


def run(inputs: dict) -> dict:
    dim = inputs["DIM_PRODUCT"].copy()
    stg = inputs["STG_PRODUCT"].copy()

    dim_cols = list(dim.columns)

    # Build mutable list of rows from existing DIM_PRODUCT
    rows = dim.to_dict("records")

    # Map product_id -> index of its current row (is_current == 1), if any.
    current_idx = {}
    for i, r in enumerate(rows):
        pid = r.get("product_id")
        is_cur = r.get("is_current")
        if is_cur == 1 or is_cur == "1":
            current_idx[pid] = i

    # Sort staged records by product_id, update_date ascending (stable sort
    # preserves original order for ties, though dates are unique per product).
    stg_sorted = stg.sort_values(
        by=["product_id", "update_date"], kind="mergesort"
    ).reset_index(drop=True)

    for _, s in stg_sorted.iterrows():
        pid = s["product_id"]
        s_category = s["category"]
        s_price_band = s["price_band"]
        s_date = s["update_date"]

        if pid not in current_idx:
            new_row = {
                "product_id": pid,
                "category": s_category,
                "price_band": s_price_band,
                "eff_start_date": s_date,
                "eff_end_date": None,
                "is_current": 1,
            }
            rows.append(new_row)
            current_idx[pid] = len(rows) - 1
        else:
            idx = current_idx[pid]
            c = rows[idx]

            changed = (not _eq_nullable(c.get("category"), s_category)) or (
                not _eq_nullable(c.get("price_band"), s_price_band)
            )

            if changed:
                rows[idx]["eff_end_date"] = s_date
                rows[idx]["is_current"] = 0

                new_row = {
                    "product_id": pid,
                    "category": s_category,
                    "price_band": s_price_band,
                    "eff_start_date": s_date,
                    "eff_end_date": None,
                    "is_current": 1,
                }
                rows.append(new_row)
                current_idx[pid] = len(rows) - 1
            # else: no-op, unchanged attributes -> no new version

    out = pd.DataFrame(rows, columns=dim_cols)

    return {"dim_product_out": out}
